-- Synthetic schema fixture generated from main@13e7d6c (v1.2); no user data.
CREATE TABLE journals (id TEXT PRIMARY KEY,title TEXT NOT NULL,market TEXT NOT NULL,issn TEXT,source TEXT,enabled INTEGER DEFAULT 0,rank_label TEXT,homepage TEXT,last_checked TEXT,last_success TEXT,last_error TEXT,last_count INTEGER DEFAULT 0,checkpoint TEXT, rank_system TEXT DEFAULT '', rank_year TEXT DEFAULT '', rank_category TEXT DEFAULT '', rank_evidence_url TEXT DEFAULT '', rank_verification_status TEXT DEFAULT 'pending', watchlist_class TEXT DEFAULT 'candidate');
CREATE TABLE articles (id TEXT PRIMARY KEY,journal_id TEXT NOT NULL,market TEXT NOT NULL,title TEXT NOT NULL,doi TEXT,url TEXT,authors TEXT,abstract TEXT,publication_date TEXT,published_year INTEGER,discovered_at TEXT NOT NULL,source TEXT NOT NULL,topics TEXT NOT NULL DEFAULT '[]',matched INTEGER NOT NULL DEFAULT 0,method TEXT,design TEXT,data_origin TEXT,sample_n INTEGER,sample_unit TEXT,evidence TEXT,ai_summary TEXT,analysis_status TEXT NOT NULL DEFAULT 'pending',demo INTEGER NOT NULL DEFAULT 0, published_online_date TEXT DEFAULT '', indexed_at TEXT DEFAULT '', date_precision TEXT DEFAULT 'unknown', publisher_landing_url TEXT DEFAULT '', link_provenance TEXT DEFAULT '', analysis_json TEXT, analysis_attempts INTEGER DEFAULT 0, analysis_error TEXT DEFAULT '', analysis_retry_at TEXT, notification_eligible INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(journal_id) REFERENCES journals(id));
CREATE TABLE subscribers (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,topics TEXT NOT NULL,markets TEXT NOT NULL,urgent INTEGER DEFAULT 1,daily INTEGER DEFAULT 1,weekly INTEGER DEFAULT 0,confirmed INTEGER DEFAULT 0,verify_hash TEXT,unsubscribe_hash TEXT,created_at TEXT,confirmed_at TEXT,last_daily TEXT,last_weekly TEXT);
CREATE TABLE deliveries (id TEXT PRIMARY KEY,subscriber_id TEXT,article_id TEXT,kind TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,error TEXT,UNIQUE(subscriber_id,article_id,kind));
CREATE TABLE jobs (id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT,status TEXT NOT NULL,details TEXT);
CREATE TABLE meta (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE scan_windows (
 journal_id TEXT PRIMARY KEY,mode TEXT NOT NULL,range_end TEXT NOT NULL,window_start TEXT NOT NULL,window_end TEXT NOT NULL,cursor TEXT NOT NULL DEFAULT '*',processed INTEGER NOT NULL DEFAULT 0,total INTEGER,attempts INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE schema_migrations(version TEXT PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE lab_manuscript_details(manuscript_id TEXT PRIMARY KEY,coauthors TEXT NOT NULL DEFAULT '',coauthor_ids TEXT NOT NULL DEFAULT '[]',target_journals TEXT NOT NULL DEFAULT '',actual_submitted_journal TEXT NOT NULL DEFAULT '',expected_date TEXT NOT NULL DEFAULT '',work_type TEXT NOT NULL DEFAULT 'article',source_json TEXT);
CREATE TABLE lab_import_batches(id TEXT PRIMARY KEY,uploaded_by TEXT NOT NULL,file_hash TEXT NOT NULL,preview_json TEXT NOT NULL,created_at TEXT NOT NULL,confirmed_at TEXT,UNIQUE(uploaded_by,file_hash));
CREATE TABLE lab_import_rows(batch_id TEXT NOT NULL,source_row INTEGER NOT NULL,manuscript_id TEXT NOT NULL,PRIMARY KEY(batch_id,source_row));
CREATE TABLE lab_project_members(project_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(project_id,user_id));
CREATE TABLE lab_project_workspace(project_id TEXT PRIMARY KEY,owner_id TEXT,start_date TEXT DEFAULT '',due_date TEXT DEFAULT '',stage TEXT DEFAULT '',progress_mode TEXT DEFAULT 'milestones');
CREATE TABLE lab_milestones(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',weight REAL NOT NULL DEFAULT 1,due_date TEXT DEFAULT '');
CREATE TABLE lab_tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,title TEXT NOT NULL,assignee_id TEXT,status TEXT NOT NULL DEFAULT 'todo',blocker TEXT DEFAULT '',due_date TEXT DEFAULT '');
CREATE TABLE lab_task_notes(task_id TEXT PRIMARY KEY,summary TEXT DEFAULT '',next_step TEXT DEFAULT '',updated_at TEXT);
CREATE TABLE lab_project_records(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,document_id TEXT,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE lab_users (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,role TEXT NOT NULL CHECK(role IN ('mentor','lab_admin','member')),password_hash TEXT NOT NULL,created_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE lab_sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES lab_users(id));
CREATE TABLE lab_projects (id TEXT PRIMARY KEY,title TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'planning',next_step TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,created_by TEXT NOT NULL);
CREATE TABLE lab_project_managers (project_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(project_id,user_id));
CREATE TABLE lab_manuscripts (id TEXT PRIMARY KEY,title TEXT NOT NULL,owner_id TEXT NOT NULL,project_id TEXT,status TEXT NOT NULL DEFAULT 'idea',private_note TEXT NOT NULL DEFAULT '',next_step TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,created_by TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES lab_users(id));
CREATE TABLE lab_member_updates (id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active',note TEXT NOT NULL DEFAULT '',next_step TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE lab_documents (id TEXT PRIMARY KEY,filename TEXT NOT NULL,mime TEXT NOT NULL,file_path TEXT NOT NULL,uploaded_by TEXT NOT NULL,uploaded_at TEXT NOT NULL,text_length INTEGER NOT NULL,extract_status TEXT NOT NULL DEFAULT 'pending',extract_error TEXT NOT NULL DEFAULT '',doc_hash TEXT NOT NULL);
CREATE TABLE lab_suggestions (id TEXT PRIMARY KEY,document_id TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,status TEXT,summary TEXT NOT NULL DEFAULT '',next_step TEXT NOT NULL DEFAULT '',source_quote TEXT NOT NULL,review_state TEXT NOT NULL DEFAULT 'pending',reviewed_by TEXT,reviewed_at TEXT, confidence REAL DEFAULT 0.5,FOREIGN KEY(document_id) REFERENCES lab_documents(id));
CREATE TABLE lab_events (id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,kind TEXT NOT NULL,visibility TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',before_json TEXT NOT NULL,after_json TEXT NOT NULL,source_document_id TEXT,source_quote TEXT,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE lab_private_manuscript_archive(manuscript_id TEXT PRIMARY KEY,private_note TEXT,next_step TEXT,archived_at TEXT NOT NULL);
CREATE INDEX idx_articles_market_date ON articles(market, publication_date DESC);
CREATE INDEX idx_articles_discovery ON articles(discovered_at DESC);
CREATE INDEX idx_articles_publication ON articles(published_online_date DESC,publication_date DESC);
CREATE INDEX idx_lab_events ON lab_events(entity_type,entity_id,created_at DESC);
CREATE INDEX idx_lab_suggestions ON lab_suggestions(document_id,review_state);
